package kiro

import (
	"context"
	"errors"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/knowlet/kiro-cli-login-watchdog/internal/config"
)

func TestKASAuthCommandHelp(t *testing.T) {
	// Fixtures were generated by the actual upstream add_kas_parser definitions,
	// not a stand-in CLI that assumes the auth verbs already exist.
	for _, tc := range []struct {
		name string
		want bool
	}{
		{"kirocrew-v0.10.0-kas-help.txt", false},
		{"kirocrew-d199f301-kas-help.txt", true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			b, err := os.ReadFile(filepath.Join("testdata", tc.name))
			if err != nil {
				t.Fatal(err)
			}
			if got := kasAuthCommandsAvailable(string(b)); got != tc.want {
				t.Fatalf("available=%v, want %v", got, tc.want)
			}
		})
	}
	for _, tc := range []struct {
		help string
		want bool
	}{
		{"", false},
		{"login whoami logout are not supported", false},
		{"{install,status,remove} --description login whoami logout", false},
		{"{login,whoami}", false},
		{"{login,whoami} {logout}", false},
		{"{login,whoami,logout-extra}", false},
		{"{ login,\n whoami, logout }", true},
		{"\x1b[32m{login,whoami,logout}\x1b[0m", true},
	} {
		if got := kasAuthCommandsAvailable(tc.help); got != tc.want {
			t.Errorf("available(%q)=%v, want %v", tc.help, got, tc.want)
		}
	}
}

func TestLegacyBackendDoesNotProbeKiroCrew(t *testing.T) {
	c := New(config.Config{KiroBin: "must-not-execute", KiroCrewBin: "must-not-execute"}, nil)
	if err := c.CheckCapabilities(context.Background()); err != nil {
		t.Fatal(err)
	}
}

func TestKASCapabilityProbeErrors(t *testing.T) {
	c := New(config.Config{Backend: config.BackendKAS,
		KiroCrewBin: filepath.Join(t.TempDir(), "absent-kirocrew"), CommandTimeout: time.Second}, nil)
	if err := c.CheckCapabilities(context.Background()); err == nil {
		t.Fatal("missing executable accepted")
	}
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	if err := c.CheckCapabilities(ctx); !errors.Is(err, context.Canceled) {
		t.Fatalf("cancellation lost: %v", err)
	}
	c.commandTimeout = -time.Second
	if err := c.CheckCapabilities(context.Background()); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("deadline lost: %v", err)
	}
}
